import { assessment, type CriterionAssessment, type EBox, type TestFinding } from "./models";
import { testById } from "./tests";

const retrieved = "2026-07-17";

type CriterionInput = Record<string, readonly [0 | 1 | 2 | 3 | 4 | null, string]>;

function scored(
  testId: string,
  finding: TestFinding,
  input: CriterionInput,
  analysis: string,
  status: "Reviewed" | "Provisional" = "Reviewed",
) {
  const test = testById.get(testId);
  if (!test) throw new Error(`Unknown test: ${testId}`);
  const criteria: CriterionAssessment[] = test.criteria.map((criterion) => {
    const value = input[criterion.id];
    return {
      criterionId: criterion.id,
      score: value?.[0] ?? null,
      rationale: value?.[1] ?? "N/A — this record does not supply enough direct evidence to score this criterion.",
    };
  });
  return assessment(testId, finding, criteria, analysis, status);
}

